/**
 * @summary Generate a professional summary using AI
 */
export const getGenerateSummaryUrl = () => {
  return `/api/ai/generate-summary`;
};

export const generateSummary = async (
  generateSummaryBody: GenerateSummaryBody,
  options?: RequestInit,
): Promise<AiTextResult> => {
  return customFetch<AiTextResult>(getGenerateSummaryUrl(), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(generateSummaryBody),
  });
};

export const getGenerateSummaryMutationOptions = <
  TError = ErrorType<ErrorResponse>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof generateSummary>>,
    TError,
    { data: BodyType<GenerateSummaryBody> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof generateSummary>>,
  TError,
  { data: BodyType<GenerateSummaryBody> },
  TContext
> => {
  const mutationKey = ["generateSummary"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof generateSummary>>,
    { data: BodyType<GenerateSummaryBody> }
  > = (props) => {
    const { data } = props ?? {};

    return generateSummary(data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type GenerateSummaryMutationResult = NonNullable<
  Awaited<ReturnType<typeof generateSummary>>
>;
export type GenerateSummaryMutationBody = BodyType<GenerateSummaryBody>;
export type GenerateSummaryMutationError = ErrorType<ErrorResponse>;

